"""优惠券：按券码对金额做减免。"""


def apply_coupon(amount, code):
    """按券码计算折后金额。

    SAVE20 立减 20 元（减到 0 为止，不会为负）；HALF 打五折；
    未知券码抛 ValueError。
    """
    if code == "SAVE20":
        return max(amount - 20, 0)
    if code == "HALF":
        return round(amount / 2, 2)
    raise ValueError(f"未知券码: {code}")
